create or replace function update_live_fixtures(live_fixtures jsonb)returns integer language plpgsql security definer set search_path=public as $$declare f jsonb;updated int:=0;begin if current_setting('request.jwt.claim.role',true)<>'service_role'then raise exception'Service role required';end if;for f in select*from jsonb_array_elements(live_fixtures)loop update matches set status=(f->>'status')::match_status,home_score=(f->>'homeScore')::int,away_score=(f->>'awayScore')::int,last_synced_at=now()where provider_id=f->>'providerId';if found then updated:=updated+1;end if;end loop;return updated;end;$$;
revoke all on function update_live_fixtures(jsonb)from public,anon,authenticated;grant execute on function update_live_fixtures(jsonb)to service_role;

create or replace function sync_live_match_details(fixture_provider_id text,normalized_events jsonb,normalized_statistics jsonb)returns jsonb language plpgsql security definer set search_path=public as $$declare target_match matches%rowtype;e jsonb;s jsonb;team_uuid uuid;player_uuid uuid;event_count int:=0;stat_count int:=0;event_key text;begin if current_setting('request.jwt.claim.role',true)<>'service_role'then raise exception'Service role required';end if;select*into target_match from matches where provider_id=fixture_provider_id;if not found then raise exception'Match not found';end if;for e in select*from jsonb_array_elements(normalized_events)loop select id into team_uuid from teams where provider='api-football'and provider_id=e->>'teamId';select id into player_uuid from players where provider='api-football'and provider_id=e->>'playerId';event_key:=md5(concat_ws('|',e->>'teamId',e->>'playerId',e->>'minute',e->>'extraMinute',e->>'type',e->>'detail'));insert into match_events(match_id,provider_event_id,event_type,team_id,player_id,minute,extra_minute,metadata_json)values(target_match.id,event_key,e->>'type',team_uuid,player_uuid,(e->>'minute')::int,nullif(e->>'extraMinute','')::int,e)on conflict(match_id,provider_event_id)do update set event_type=excluded.event_type,team_id=excluded.team_id,player_id=excluded.player_id,minute=excluded.minute,extra_minute=excluded.extra_minute,metadata_json=excluded.metadata_json;event_count:=event_count+1;end loop;for s in select*from jsonb_array_elements(normalized_statistics)loop select id into team_uuid from teams where provider='api-football'and provider_id=s->>'teamId';if team_uuid is not null then insert into match_statistics(match_id,entity_type,entity_id,stat_type,value)values(target_match.id,'TEAM',team_uuid,'CORNERS',(s->>'corners')::numeric)on conflict(match_id,entity_type,entity_id,stat_type)do update set value=excluded.value,updated_at=now();insert into match_statistics(match_id,entity_type,entity_id,stat_type,value)values(target_match.id,'TEAM',team_uuid,'SHOTS_ON_TARGET',(s->>'shotsOnTarget')::numeric)on conflict(match_id,entity_type,entity_id,stat_type)do update set value=excluded.value,updated_at=now();stat_count:=stat_count+2;end if;end loop;return jsonb_build_object('events',event_count,'statistics',stat_count);end;$$;
revoke all on function sync_live_match_details(text,jsonb,jsonb)from public,anon,authenticated;grant execute on function sync_live_match_details(text,jsonb,jsonb)to service_role;

create or replace function get_live_match_snapshots()returns table(snapshot jsonb)language sql stable security definer set search_path=public as $$
 select jsonb_build_object('id',m.provider_id,'competition',c.name,'round',coalesce(r.name,'Live'),'kickoffAt',m.kickoff_at,'status',m.status,'home',jsonb_build_object('id',home.provider_id,'name',home.name,'shortName',home.short_name,'logoUrl',home.logo_url,'score',m.home_score),'away',jsonb_build_object('id',away.provider_id,'name',away.name,'shortName',away.short_name,'logoUrl',away.logo_url,'score',m.away_score),'events',coalesce((select jsonb_agg(jsonb_build_object('type',me.event_type,'detail',me.metadata_json->>'detail','minute',me.minute,'extraMinute',me.extra_minute,'teamId',t.provider_id,'playerName',p.name)order by me.minute,me.extra_minute nulls first)from match_events me left join teams t on t.id=me.team_id left join players p on p.id=me.player_id where me.match_id=m.id),'[]'::jsonb),'statistics',jsonb_build_object('home',jsonb_build_object('corners',(select value from match_statistics where match_id=m.id and entity_id=home.id and stat_type='CORNERS'),'shotsOnTarget',(select value from match_statistics where match_id=m.id and entity_id=home.id and stat_type='SHOTS_ON_TARGET')),'away',jsonb_build_object('corners',(select value from match_statistics where match_id=m.id and entity_id=away.id and stat_type='CORNERS'),'shotsOnTarget',(select value from match_statistics where match_id=m.id and entity_id=away.id and stat_type='SHOTS_ON_TARGET'))),'lastSyncedAt',m.last_synced_at)
 from matches m join competitions c on c.id=m.competition_id left join competition_rounds r on r.id=m.round_id join teams home on home.id=m.home_team_id join teams away on away.id=m.away_team_id where m.status='LIVE' order by m.kickoff_at;
$$;
grant execute on function get_live_match_snapshots()to anon,authenticated;
